### 5.1 New module constants + helpers (add near `_MUTATING_TOOLS`)

```python
# --- usefulness oracle (pass-but-useless detection) ---
_MIN_CONTENT_CHARS = 40
_MUTATION_VERBS = ("write", "create", "edit", "update", "add", "fix",
                   "implement", "refactor", "patch", "append", "delete")
_SPEC_STOP = {"that", "this", "with", "from", "your", "have", "must",
              "should", "every", "claim", "the", "and", "for", "not"}

def _implies_mutation(spec: str) -> bool:
    low = (spec or "").lower()
    return any(v in low for v in _MUTATION_VERBS) or any(
        t in low for t in ("write_file", "run_python", "run_shell", "edit_file")
    )

def _spec_tokens_present(text: str, spec: str) -> bool:
    spec_tokens = {w for w in re.findall(r"[a-z0-9]{4,}", (spec or "").lower())
                   if w not in _SPEC_STOP}
    if not spec_tokens:
        return True  # no spec tokens to check -> not a mismatch
    text_tokens = set(re.findall(r"[a-z0-9]{4,}", (text or "").lower()))
    return bool(spec_tokens & text_tokens)

def detect_useless_output(*, text, turn_mutated, spec_hint="",
                          min_content_chars=_MIN_CONTENT_CHARS) -> dict:
    t = (text or "").strip()
    if not t:
        return {"verdict": "empty", "reason": "no output text"}
    if len(t) < min_content_chars:
        return {"verdict": "low_content", "reason": f"only {len(t)} chars"}
    if not turn_mutated and _claims_edit(t):
        return {"verdict": "false_success", "reason": "claimed edits, no mutating tool"}
    if spec_hint and not turn_mutated and _implies_mutation(spec_hint):
        return {"verdict": "no_mutating_tool", "reason": "spec implied mutation, none ran"}
    if spec_hint and not _spec_tokens_present(t, spec_hint):
        return {"verdict": "spec_mismatch", "reason": "output missing spec tokens"}
    return {"verdict": "useful", "reason": "ok"}
```

